"""Build the final relative-path asset contract after render and static QA."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[1];variants=[]
for name,label,cue in [('hush','Hush · 低阔','宽罩、低拱、短柱'),('poise','Poise · 均衡','中等罩宽、弧冠与高度'),('reach','Reach · 窄高','窄罩、高冠、长柱')]:
 folder=root/'assets'/name;info=json.loads((folder/'model-info.json').read_text());qa=json.loads((folder/'validation.json').read_text());glb=json.loads((folder/'glb-validation.json').read_text());assert qa['passed'] and glb['passed'] and info['validation_status']=='static-QA-passed'
 paths={k:f'assets/{name}/{v}' for k,v in {'model_blend':'model.blend','model_glb':'model.glb','scene_blend':'scene.blend','preview':'beauty.png','front':'front.png','side':'side.png','top':'top.png','junction':'junction.png','base_junction':'base-junction.png','info':'model-info.json','qa':'validation.json','glb_qa':'glb-validation.json'}.items()}
 assert all((root/p).is_file() for p in paths.values());variants.append({'id':name,'label':label,'geometric_difference':cue,'dimensions_mm':info['dimensions_mm'],'parameters':info['config'],'triangles':info['triangles'],'mesh_objects':8,'materials':3,'paths':paths,'qa_passed':True,'sampled_shell_diffuser_min_mm':qa['shell_diffuser_clearance']['sampled_vertex_surface_min_mm'],'glb_sha256':hashlib.sha256((folder/'model.glb').read_bytes()).hexdigest()})
m={'schema_version':1,'study':'005','title':'Vesper / 暮灯','recipe_version':'1.1.0','seed':0,'blender_version':'4.3.2','status':'static-QA-passed; pending independent visual signoff','units':'metres','source_up_axis':'Z','glb_up_axis':'Y','original_geometry':True,'external_images':False,'runtime_verified':False,'gpu_verified':False,'iphone_verified':False,'dynamic_z_fighting_verified':False,'variants':variants,'fixed_construction':{'shell_vertical_thickness_mm':6,'diffuser_vertical_thickness_mm':4,'diffuser_radial_ratio':.86,'reference_rim_offset_mm':16,'base_height_mm':26,'pin_count':3},'renderer':{'engine':'Cycles CPU','hero_samples':1024,'orthographic_samples':384,'junction_samples':256,'denoiser':'none (not available in this Blender build)','view_transform':'AgX','exposure':-.4,'fixed_camera_views':['beauty','front','side','top'],'variant_local_views':['junction','base-junction'],'glb_contains_studio':False},'documentation':{'readme':'README.md','parameter_schema':'config.schema.json','source':'source/generate.py','transactional_cli':'source/run.py','full_test_cli':'source/test_all.py','references':'review/reference-notes.md','reflection':'review/reflection.md','contract_tests':'review/invalid-input-tests.json','adversarial_tests':'review/adversarial-qa-tests.json','reproducibility':'review/reproducibility.json','before':'review/before.png','after':'review/after.png','contact_sheet':'review/contact-sheet.png'},'limits':['Static discrete validation only; continuous parameter domain not proved.','Luminous diffuser is an emissive visual proxy, not a calibrated optical simulation.','No manufacturing, stability, electrical, thermal, or safety certification.','Real-time GL/GPU/iPhone/flicker not tested.']}
m['viewer']={'html':'view.html','script':'viewer.js','style':'viewer.css','vendor':'vendor/','three_revision':'180','actual_glb_parse_test':'review/three-loader-tests.json','state_tests':'review/viewer-state-tests.json','gpu_verified':False}
m['documentation'].update(independent_review='review/independent-review.md',junction_feature_evidence='review/junction-feature-evidence.json',junction_feature_map='review/junction-feature-map.png',socket_inspection='review/socket-inspection.png',source_archive='recipe-source.zip')
(root/'manifest.json').write_text(json.dumps(m,indent=2,ensure_ascii=False));print('manifest ready')
